import assert from 'node:assert/strict';
import {describe, test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

describe('Router registration and error handling', () => {
  const router = makeRouter();

  test('routes are registered in correct order with correct methods', () => {
    assert.equal(router.routes.length, 5);
    assert.deepEqual(
      router.routes.map(r => ({ method: r.method, path: r.path })),
      [
        { method: 'GET', path: '/accounts/:id' },
        { method: 'POST', path: '/accounts' },
        { method: 'GET', path: '/health' },
        { method: 'GET', path: '/orders/:id' },
        { method: 'DELETE', path: '/orders/:id' },
      ]
    );
  });

  test('GET /accounts/:id handles success and returns response', async () => {
    const route = router.routes[0];
    let nextCalled = false;
    const res = { send: (val) => `sent:${val}` };
    const result = await route.handler({ id: 'acc1' }, res, () => { nextCalled = true; });
    assert.equal(result, 'sent:account:acc1');
    assert.equal(nextCalled, false);
  });

  test('GET /accounts/:id forwards failure to next', async () => {
    const route = router.routes[0];
    let forwardedError = null;
    const res = { send: (val) => `sent:${val}` };
    await route.handler({ id: 'acc1', fail: true }, res, (err) => { forwardedError = err; });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account read');
  });

  test('POST /accounts (named async function) handles success and returns response', async () => {
    const route = router.routes[1];
    let nextCalled = false;
    const res = { send: (val) => `sent:${val}` };
    const result = await route.handler({ id: 'acc2' }, res, () => { nextCalled = true; });
    assert.equal(result, 'sent:created:acc2');
    assert.equal(nextCalled, false);
  });

  test('POST /accounts forwards failure to next', async () => {
    const route = router.routes[1];
    let forwardedError = null;
    const res = { send: (val) => `sent:${val}` };
    await route.handler({ id: 'acc2', fail: true }, res, (err) => { forwardedError = err; });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'account create');
  });

  test('GET /health synchronous route is preserved and returns ok synchronously', () => {
    const route = router.routes[2];
    let nextCalled = false;
    const res = { send: (val) => val };
    const result = route.handler({ id: 'test' }, res, () => { nextCalled = true; });
    assert.equal(result, 'ok');
    assert.equal(nextCalled, false);
  });

  test('GET /orders/:id handles success and returns response', async () => {
    const route = router.routes[3];
    let nextCalled = false;
    const res = { send: (val) => `sent:${val}` };
    const result = await route.handler({ id: 'ord1' }, res, () => { nextCalled = true; });
    assert.equal(result, 'sent:ORD1');
    assert.equal(nextCalled, false);
  });

  test('GET /orders/:id forwards failure to next', async () => {
    const route = router.routes[3];
    let forwardedError = null;
    const res = { send: (val) => `sent:${val}` };
    await route.handler({ id: 'ord1', fail: true }, res, (err) => { forwardedError = err; });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order read');
  });

  test('DELETE /orders/:id handles success and returns response', async () => {
    const route = router.routes[4];
    let nextCalled = false;
    const res = { send: (val) => `sent:${val}` };
    const result = await route.handler({ id: 'ord2' }, res, () => { nextCalled = true; });
    assert.equal(result, 'sent:deleted:ord2');
    assert.equal(nextCalled, false);
  });

  test('DELETE /orders/:id forwards failure to next', async () => {
    const route = router.routes[4];
    let forwardedError = null;
    const res = { send: (val) => `sent:${val}` };
    await route.handler({ id: 'ord2', fail: true }, res, (err) => { forwardedError = err; });
    assert.ok(forwardedError instanceof Error);
    assert.equal(forwardedError.message, 'order delete');
  });

  test('unrelated async helper is not wrapped', async () => {
    await assert.rejects(
      async () => { await unrelatedHelper(); },
      { name: 'Error', message: 'helper' }
    );
  });

  test('unrelated audit callback is not wrapped', async () => {
    await assert.rejects(
      async () => { await auditCallback(); },
      { name: 'Error', message: 'audit' }
    );
  });
});

